int bk7258_bringup(void)
{
  uint32_t button_count;
  int ret;

  button_count = board_button_initialize();
#ifdef CONFIG_FS_PROCFS
  /* Mount procfs first so that ps, free and the other informational NSH
   * commands work even if a later bring-up step returns early. A mount
   * failure is reported but never blocks bring-up: procfs is not required
   * by the console data path.
   */

  ret = nx_mount(NULL, "/proc", "procfs", 0, NULL);
  if (ret < 0)
    {
      printf("failed to mount procfs at /proc, error=%d\n", ret);
    }
#endif

  ret = bk7258_motor_setup();
  if (ret < 0)
    {
      return ret;
    }

  ret = bk7258_mailbox_wait_link_ready(BK7258_LINK_WAIT_MS);
  if (ret < 0)
    {
      printf("mailbox UART0 STATE probe failed, error=%d\n", ret);
      bk7258_mailbox_dump_stats();
      bk7258_mbox_uart_dump_stats();
      return ret;
    }

  printf("mailbox UART0 link ready\n");

  ret = bk7258_ipc_heartbeat_start();
  if (ret < 0)
    {
      printf("HW_CTRL power-up service failed, error=%d\n", ret);
      bk7258_mailbox_dump_stats();
      return ret;
    }

  ret = bk7258_pwc_start();
  if (ret < 0)
    {
      return ret;
    }

#ifdef CONFIG_BK7258_WIFI
  ret = bk7258_wifi_initialize();
  if (ret < 0)
    {
      return ret;
    }
#endif

  printf("button GPIOs configured, count=%lu\n",
         (unsigned long)button_count);
  printf("PWM device registered at /dev/pwm0\n");
  printf("mailbox transport, PWC and CPU1 ready handshake complete\n");
  printf("heartbeat worker started, interval=2000 ms\n");
#ifdef CONFIG_BK7258_PSRAM
  if (bk7258_psram_is_online())
    {
      printf("PSRAM online, base=0x60000000 size=0x01000000 "
             "RW/XN/non-cacheable\n");

      /* PSRAM-backed /dev/ram0: the only storage on this board big enough
       * to hold a captured frame as a file (tmpfs lives in the ~300KB
       * kernel heap, one 640x480 YUYV frame is 614400 bytes).
       */

      (void)bk7258_ramdisk_initialize();
      /* printf("PSRAM CP heap 0x60700000..0x6071ffff reserved\n"); */
      /* bk7258_psram_dump(); */
    }
  else
    {
      printf("PSRAM unavailable; media services must remain disabled\n");
    }
#endif

  ret = bk7258_power_key_motor_start();
  if (ret < 0)
    {
      return ret;
    }

  return 0;
}

/****************************************************************************
 * Name: bk7258_report_cache
 *
 * Description:
 *   Reports whether this core implements instruction and data caches.
 *
 *   The AP executes in place from flash at 0x02150000 and NuttX never enables
 *   a cache: CONFIG_ARMV8M_ICACHE depends on ARMV8M_HAVE_ICACHE, which the
 *   BK7258 chip Kconfig does not select, so setting it in a defconfig is
 *   silently dropped.  That matters because measured throughput here is what
 *   you would expect from uncached instruction fetch out of QSPI flash: the
 *   expression renderer costs ~450ms per frame for work that takes 0.09ms on
 *   a host, a 51200-byte word-at-a-time copy runs at 0.8MB/s, and raising the
 *   core to 480MHz changed none of it.
 *
 *   Whether the cache can be turned on is not obvious from the vendor tree:
 *   bk7258.defconfig sets CONFIG_CACHE_ENABLE=n and their cache.c guards
 *   every D-cache operation with a runtime CLIDR test.  CLIDR/CTR exist in
 *   ARMv8-M whether or not a cache is fitted (they read zero when it is not),
 *   so reading them is safe and settles the question.
 *
 ****************************************************************************/

static void bk7258_report_cache(void)
{
  uint32_t clidr = getreg32(0xe000ed78);   /* SCB->CLIDR */
  uint32_t ctr   = getreg32(0xe000ed7c);   /* SCB->CTR   */
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_ramdisk.c
 *
 * PSRAM-backed RAM disk so that captured frames can be written to a real
 * file ("file mode" of apps/system/nxcamera's `output <path> [nframes]`).
 *
 * Why this exists: the only writable filesystem this board had was tmpfs,
 * whose storage comes from the kernel heap.  CONFIG_RAM_SIZE is 344064
 * bytes and roughly 300KB of that is heap, while one 640x480 YUYV frame is
 * 614400 bytes -- so `output /tmp/frame.yuv 1` could never succeed, the
 * write() always failed with ENOMEM.  This board does, however, have 16MB
 * of PSRAM with a 2.9MB general-purpose AP heap (see bk7258_psram.c), so a
 * RAM disk carved out of PSRAM gives the filesystem enough room for
 * several full frames without touching the kernel heap at all.
 *
 * Usage after boot (the ramdisk is registered but intentionally left
 * unformatted, since its contents are volatile anyway):
 *
 *   mkfatfs /dev/ram0
 *   mount -t vfat /dev/ram0 /mnt
 *   nxcamera
 *     input /dev/video0
 *     output /mnt/frame.yuv 1     <- exactly one frame, then stream stops
 *     stream 640 480 30 YUYV
 *     q
 *   ls -l /mnt
 *   hexdump /mnt/frame.yuv count=64
 *
 * The .yuv file is raw YUYV (YUV422), so on a host it converts with e.g.
 *   ffmpeg -f rawvideo -pix_fmt yuyv422 -s 640x480 -i frame.yuv frame.png
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdio.h>
#include <errno.h>

#include <nuttx/drivers/ramdisk.h>

#include "bk7258_psram.h"
#include "bk7258_ramdisk.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define BK7258_RAMDISK_MINOR      0
#define BK7258_RAMDISK_SECTOR     512u

/* 2MB: enough for three 640x480 YUYV frames plus FAT overhead, out of the
 * 2.9MB AP PSRAM heap (BK7258_AP_PSRAM_HEAP_*, bk7258_psram.c).  The V4L2
 * capture buffers do not come from this heap -- they are allocated from the
 * separate PSRAM DISPLAY pool by bk7258_camera_imgdata.c -- so the two do
 * not compete.
 */

#define BK7258_RAMDISK_BYTES      (2u * 1024u * 1024u)
#define BK7258_RAMDISK_SECTORS    (BK7258_RAMDISK_BYTES / BK7258_RAMDISK_SECTOR)

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int bk7258_ramdisk_initialize(void)
{
#ifdef CONFIG_BK7258_PSRAM
  FAR uint8_t *buffer;
  int ret;

  if (!bk7258_psram_is_online())
    {
      printf("ramdisk: PSRAM offline, /dev/ram0 not registered\n");
      return -ENODEV;
    }

  buffer = bk7258_psram_memalign(BK7258_RAMDISK_SECTOR,
                                 BK7258_RAMDISK_BYTES);
  if (buffer == NULL)
    {
      printf("ramdisk: PSRAM allocation of %u bytes failed\n",
             (unsigned int)BK7258_RAMDISK_BYTES);
      return -ENOMEM;
    }

  ret = ramdisk_register(BK7258_RAMDISK_MINOR, buffer,
                         BK7258_RAMDISK_SECTORS, BK7258_RAMDISK_SECTOR,
                         RDFLAG_WRENABLED);
  if (ret < 0)
    {
      printf("ramdisk: ramdisk_register failed, error=%d\n", ret);
      bk7258_psram_free(buffer);
      return ret;
    }

  printf("ramdisk: /dev/ram0 registered, %u KB at %p (PSRAM); format with "
         "\"mkfatfs /dev/ram0\" then \"mount -t vfat /dev/ram0 /mnt\"\n",
         (unsigned int)(BK7258_RAMDISK_BYTES / 1024u), buffer);

  return OK;
#else
  return -ENOTSUP;
#endif
}

/* ── Startup timing helpers ───────────────────────────────────── */

static inline long boot_ms(struct timespec* t0)
{
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    return (long)((now.tv_sec - t0->tv_sec) * 1000L + (now.tv_nsec - t0->tv_nsec) / 1000000L);
}

#define BOOT_LOG(t0, phase, msg) \
    syslog(LOG_INFO, "[%s] [boot +%ldms] " phase ": " msg "\n", TAG, boot_ms(t0))

#define BOOT_LOG_RC(t0, phase, msg, rc) \
    syslog((rc) == OK ? LOG_INFO : LOG_WARNING, \
        "[%s] [boot +%ldms] " phase ": " msg " (rc=%d)\n", TAG, boot_ms(t0), (rc))

int ai_agent_main(int argc, char* argv[])
{
    (void)argc;
    (void)argv;

    g_shutdown_requested = false;

    struct timespec t0;
    clock_gettime(CLOCK_MONOTONIC, &t0);

    syslog(LOG_INFO, "[%s] AI Agent - Vela AI Agent starting (build: %s)\n",
        TAG, AGENT_BUILD_VERSION);

    /* ── Phase 0: Timezone ──────────────────────────────────── */
    /* Set TZ before any time calls so localtime_r returns CST+8.
     * NuttX with CONFIG_LIBC_LOCALTIME+CONFIG_LIBC_ZONEINFO supports
     * both POSIX ("CST-8") and zoneinfo ("Asia/Shanghai") formats. */
    setenv("TZ", AGENT_TIMEZONE, 1);
#ifdef CONFIG_LIBC_LOCALTIME
    tzset();
#endif
    BOOT_LOG(&t0, "P0", "timezone set");

    /* ── Phase 0: Storage Bootstrapping (Auto-mount & Mkdir) ── */

    struct stat st;
    if (stat("/data", &st) != 0) {
        syslog(LOG_INFO, "[%s] Mounting /data as tmpfs for simulation...\n", TAG);
        mount(NULL, "/data", "tmpfs", 0, NULL);
    }

    /* Ensure directory structure exists (No more manual mkdir needed!) */
    mkdir("/data/agent", 0755);
    mkdir("/data/agent/config", 0755);
    mkdir("/data/agent/memory", 0755);
    mkdir("/data/agent/sessions", 0755);
    mkdir("/data/agent/skills", 0755);
    BOOT_LOG(&t0, "P0", "storage ready");

    /* Memory info */
    {
        struct mallinfo mi = mallinfo();
        syslog(LOG_INFO, "[%s] [boot +%ldms] heap: arena=%d free=%d used=%d\n",
            TAG, boot_ms(&t0), mi.arena, mi.fordblks, mi.uordblks);
    }

    /* ── Phase 1: Core infrastructure ──────────────────────── */
    {
        int rc;
        rc = config_store_init();
        BOOT_LOG_RC(&t0, "P1", "config_store_init", rc);

        rc = message_bus_init();
        BOOT_LOG_RC(&t0, "P1", "message_bus_init", rc);
        if (rc != OK)
            return -1;

        rc = memory_store_init();
        BOOT_LOG_RC(&t0, "P1", "memory_store_init", rc);

        rc = session_mgr_init();
        BOOT_LOG_RC(&t0, "P1", "session_mgr_init", rc);
    }

    /* ── Phase 2: Proxy / networking ───────────────────────── */
    {
        int rc = http_proxy_init();
        BOOT_LOG_RC(&t0, "P2", "http_proxy_init", rc);
    }

    /* ── Phase 3: Application services ─────────────────────── */
    {
        int rc;
#ifdef CONFIG_AI_AGENT_FEISHU
        rc = feishu_bot_init();
        BOOT_LOG_RC(&t0, "P3", "feishu_bot_init", rc);
#endif

        rc = llm_proxy_init();
        BOOT_LOG_RC(&t0, "P3", "llm_proxy_init", rc);

        rc = llm_router_init();
        BOOT_LOG_RC(&t0, "P3", "llm_router_init", rc);

        /* node_manager must init BEFORE tool_registry so it can
         * register itself as a tool provider. */
#ifdef CONFIG_AI_AGENT_NODE
        rc = node_manager_init();
        BOOT_LOG_RC(&t0, "P3", "node_manager_init", rc);
#endif

        rc = tool_registry_init();
        BOOT_LOG_RC(&t0, "P3", "tool_registry_init", rc);

        rc = tool_guard_init();
        BOOT_LOG_RC(&t0, "P3", "tool_guard_init", rc);

        /* Skills must init AFTER tool_registry so executable skills
         * can register themselves as tools. */
        rc = skill_loader_init();
        BOOT_LOG_RC(&t0, "P3", "skill_loader_init", rc);

        rc = agent_loop_init();
        BOOT_LOG_RC(&t0, "P3", "agent_loop_init", rc);

        rc = cron_service_init();
        BOOT_LOG_RC(&t0, "P3", "cron_service_init", rc);

        rc = heartbeat_init();
        BOOT_LOG_RC(&t0, "P3", "heartbeat_init", rc);

#ifdef CONFIG_AI_AGENT_NODE
        rc = node_client_init();
        BOOT_LOG_RC(&t0, "P3", "node_client_init", rc);
    mkdir("/data/agent/memory", 0755);
    mkdir("/data/agent/sessions", 0755);
    mkdir("/data/agent/skills", 0755);
    BOOT_LOG(&t0, "P0", "storage ready");

    /* Memory info */
    {
        struct mallinfo mi = mallinfo();
        syslog(LOG_INFO, "[%s] [boot +%ldms] heap: arena=%d free=%d used=%d\n",
            TAG, boot_ms(&t0), mi.arena, mi.fordblks, mi.uordblks);
    }

    /* ── Phase 1: Core infrastructure ──────────────────────── */
    {
        int rc;
        rc = config_store_init();
        BOOT_LOG_RC(&t0, "P1", "config_store_init", rc);

        rc = message_bus_init();
        BOOT_LOG_RC(&t0, "P1", "message_bus_init", rc);
        if (rc != OK)
            return -1;

        rc = memory_store_init();
        BOOT_LOG_RC(&t0, "P1", "memory_store_init", rc);

        rc = session_mgr_init();
        BOOT_LOG_RC(&t0, "P1", "session_mgr_init", rc);
    }

    /* ── Phase 2: Proxy / networking ───────────────────────── */
    {
        int rc = http_proxy_init();
        BOOT_LOG_RC(&t0, "P2", "http_proxy_init", rc);
    }

    /* ── Phase 3: Application services ─────────────────────── */
    {
        int rc;
#ifdef CONFIG_AI_AGENT_FEISHU
        rc = feishu_bot_init();
        BOOT_LOG_RC(&t0, "P3", "feishu_bot_init", rc);
#endif

        rc = llm_proxy_init();
        BOOT_LOG_RC(&t0, "P3", "llm_proxy_init", rc);

        rc = llm_router_init();
        BOOT_LOG_RC(&t0, "P3", "llm_router_init", rc);

        /* node_manager must init BEFORE tool_registry so it can
         * register itself as a tool provider. */
#ifdef CONFIG_AI_AGENT_NODE
        rc = node_manager_init();
        BOOT_LOG_RC(&t0, "P3", "node_manager_init", rc);
#endif

        rc = tool_registry_init();
        BOOT_LOG_RC(&t0, "P3", "tool_registry_init", rc);

        rc = tool_guard_init();
        BOOT_LOG_RC(&t0, "P3", "tool_guard_init", rc);

        /* Skills must init AFTER tool_registry so executable skills
         * can register themselves as tools. */
        rc = skill_loader_init();
        BOOT_LOG_RC(&t0, "P3", "skill_loader_init", rc);

        rc = agent_loop_init();
        BOOT_LOG_RC(&t0, "P3", "agent_loop_init", rc);

        rc = cron_service_init();
        BOOT_LOG_RC(&t0, "P3", "cron_service_init", rc);

        rc = heartbeat_init();
        BOOT_LOG_RC(&t0, "P3", "heartbeat_init", rc);

#ifdef CONFIG_AI_AGENT_NODE
        rc = node_client_init();
        BOOT_LOG_RC(&t0, "P3", "node_client_init", rc);
#endif

#ifdef CONFIG_AI_AGENT_MQTT
        rc = mqtt_channel_init();
        BOOT_LOG_RC(&t0, "P3", "mqtt_channel_init", rc);
#endif

        rc = voice_channel_init();
        BOOT_LOG_RC(&t0, "P3", "voice_channel_init", rc);

#ifdef CONFIG_AI_AGENT_WEIXIN
        rc = weixin_channel_init();
        BOOT_LOG_RC(&t0, "P3", "weixin_channel_init", rc);
#endif

#ifdef CONFIG_AI_AGENT_LVGL_UI
        rc = lvgl_ui_channel_init();
        BOOT_LOG_RC(&t0, "P3", "lvgl_ui_channel_init", rc);
#endif
    }

  uint32_t ctr   = getreg32(0xe000ed7c);   /* SCB->CTR   */
  unsigned int l1 = clidr & 7;

  printf("cache: CLIDR=0x%08" PRIx32 " CTR=0x%08" PRIx32
         " L1=%s%s%s\n", clidr, ctr,
         (l1 & 1) != 0 ? "I" : "",
         (l1 & 2) != 0 ? "D" : "",
         l1 == 0 ? "none (uncached XIP from flash)" :
         (l1 == 3 ? " (separate I and D)" : ""));
}

void board_late_initialize(void)
{
  int ret = bk7258_bringup();

  bk7258_report_cache();

  if (ret < 0)
    {
      printf("board bring-up stopped, error=%d\n", ret);
      return;
    }

  printf("board bring-up initialization completed\n");

  /* GC9D01 QSPI panel bring-up smoke test.  board_app_finalinitialize()
   * (BOARDIOC_FINALINIT) is never invoked in this minimal, apps-less NSH
   * configuration (no CONFIG_BOARDCTL_FINALINIT, no apps/nshlib start-up
   * script caller), so the test entry point is invoked here instead, from
   * the unconditionally-called CONFIG_BOARD_LATE_INITIALIZE hook.  See
   * docs/superpowers/plans/2026-07-29-gc9d01-lcd-bringup.md Task 3 Step 3.
   */
#ifdef CONFIG_BK7258_GC9D01_FB
  /* GC9D01 framebuffers, one per populated panel: fb_register() calls
   * up_fbinitialize(), which does the rail/reset/bus bring-up and the init
   * sequence and allocates a 51200-byte RGB565 framebuffer, then publishes
   * /dev/fb<display>.
   *
   * Both panels are registered unconditionally.  GC9D01 has no readable ID
   * register, so an unpopulated footprint cannot be distinguished from a
   * working panel -- every command still "completes".  Registering /dev/fb1
   * on a single-panel board therefore costs one unused 51200-byte buffer
   * and nothing else; refusing to register it would need board-variant
   * configuration that this board provides no way to detect.
   */

  {
    int display;
    int registered = 0;

    for (display = 0; display < GC9D01_NDISPLAYS; display++)
      {
        ret = fb_register(display, 0);
        if (ret < 0)
          {
            printf("fb_register(%d) failed: %d\n", display, ret);
            continue;
          }

        registered |= 1 << display;
        printf("fb: /dev/fb%d registered\n", display);
      }

    /* Boot greeting, written out rather than simply appearing.
     *
     * The panel has no readable ID register, so "the init sequence was sent"
     * has never been evidence that it worked; something has to be drawn at
     * boot or a dead panel looks exactly like a working one.
     *
     * Both panels are revealed together, one column band per step, so the
     * word is written left to right.  The cost is real -- each step pushes a
     * full frame to both panels -- so it is bounded to a few hundred
     * milliseconds and measured in the log.
     *
     * The pen-stroke version of this lives in the 'hello' shell command,
     * which has a proper stroke font.  It cannot be reused here: it is an
     * application, and this configuration builds neither exec_builtin() nor
     * posix_spawn(), so bring-up has no way to start it.
     */

    if (registered != 0)
      {
        (void)bk7258_gc9d01_fb_hello_animate(registered, 20);
      }
  }
#endif

  /* GC2145 camera: registered as a standard V4L2 /dev/video0 node here
   * (imgdata+imgsensor framework, see bk7258_camera_bringup.c), superseding
   * the older bare board_late_initialize() smoke-test call this line used
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <stddef.h>
#include <stdint.h>

/* NOTE: board_app_finalinitialize() (BOARDIOC_FINALINIT) is only invoked by
 * apps/nshlib after the NSH start-up script, which requires
 * CONFIG_BOARDCTL_FINALINIT and the apps/ framework -- neither is enabled
 * in this minimal NSH configuration, so this hook is dead code here.  The
 * GC9D01 bring-up test is instead invoked from board_late_initialize() in
 * bk7258_bringup.c, which is unconditionally called via
 * CONFIG_BOARD_LATE_INITIALIZE.  See
 * docs/superpowers/plans/2026-07-29-gc9d01-lcd-bringup.md Task 3 Step 3.
 */

int board_app_finalinitialize(uintptr_t arg)
{
  return 0;
}

